const bootEl = document.getElementById('bootlog');
let bi = 0;
function typeBoot(){
  if(bi < bootLines.length){
    const line = document.createElement('div');
    line.className = 'ok';
    bootEl.appendChild(line);
    let ci = 0;
    const txt = bootLines[bi];
    const iv = setInterval(()=>{
      line.textContent = txt.slice(0, ci+1);
      ci++;
      if(ci >= txt.length){ clearInterval(iv); bi++; setTimeout(typeBoot, 90); }
    }, 8);
  }
}
typeBoot();

