const roles = [
  "Cybersecurity Enthusiast",
  "Web Penetration Tester",
  "Ethical Hacking Practitioner",
  "AI & Machine Learning Student",
  "Kali Linux / Nmap / Wireshark"
];
const roleEl = document.getElementById('roleline');
let ri = 0, ci2 = 0, deleting = false;
function tickRole(){
  const current = roles[ri];
  if(!deleting){
    ci2++;
    roleEl.textContent = current.slice(0, ci2);
    if(ci2 === current.length){ deleting = true; setTimeout(tickRole, 1400); return; }
  } else {
    ci2--;
    roleEl.textContent = current.slice(0, ci2);
    if(ci2 === 0){ deleting = false; ri = (ri+1) % roles.length; }
  }
  setTimeout(tickRole, deleting ? 35 : 65);
}
setTimeout(tickRole, 1200);

/* ================= PHOTO MATRIX-DECODE + PIXELATE REVEAL ================= */
(function(){
  const canvas = document.getElementById('heroPhotoCanvas');
  if(!canvas) return;
  const ctx = canvas.getContext('2d');
  const img = new Image();
  img.src = "data:image/jpeg;base64,";

  const matrixChars = "アイウエオカキクケコサシスセソ01ABCDEFGHIJKLMNOPQRSTUVWXYZ$#@%&*";

  img.onload = function(){
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(rect.width * dpr);
    canvas.height = Math.round(rect.height * dpr);
    const cw = canvas.width, ch = canvas.height;

    // cover-fit source crop (like object-fit:cover, biased toward top for faces)
    const iw = img.width, ih = img.height;
    const targetRatio = cw / ch;
    const srcRatio = iw / ih;
    let sx, sy, sw, sh;
    if(srcRatio > targetRatio){
      sh = ih;
      sw = ih * targetRatio;
      sy = 0;
      sx = (iw - sw) / 2;
    } else {
      sw = iw;
      sh = iw / targetRatio;
      sx = 0;
      sy = (ih - sh) * 0.12;
    }

    const off = document.createElement('canvas');
    const offCtx = off.getContext('2d');

    function drawPixelatedPhoto(pixelSize){
      const smallW = Math.max(1, Math.round(cw / pixelSize));
      const smallH = Math.max(1, Math.round(ch / pixelSize));
      off.width = smallW;
      off.height = smallH;
      offCtx.imageSmoothingEnabled = true;
      offCtx.clearRect(0, 0, smallW, smallH);
      offCtx.drawImage(img, sx, sy, sw, sh, 0, 0, smallW, smallH);

      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(off, 0, 0, smallW, smallH, 0, 0, cw, ch);
    }

    const cell = Math.max(10, Math.round(cw / 22));
    const cols = Math.ceil(cw / cell);
    const rows = Math.ceil(ch / cell);
    ctx.font = cell + "px 'JetBrains Mono', monospace";
    ctx.textBaseline = 'top';

    function drawMatrixGrid(alpha){
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.fillStyle = '#02100a';
      ctx.fillRect(0, 0, cw, ch);
      ctx.fillStyle = '#33ff66';
      for(let r = 0; r < rows; r++){
        for(let c = 0; c < cols; c++){
          const ch_ = matrixChars[Math.floor(Math.random() * matrixChars.length)];
          ctx.fillText(ch_, c * cell, r * cell);
        }
      }
      ctx.restore();
    }

    const CHUNKY_PIXEL = 26; // how blocky the photo looks right after the matrix decode

    function drawPhotoLayer(alpha, pixelSize){
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.imageSmoothingEnabled = pixelSize <= 1;
      drawPixelatedPhoto(pixelSize);
      ctx.restore();
    }

    // Phase 1: pure matrix code, flickering
    let flickerCount = 0;
    const totalFlickers = 9;
    const flickerInterval = 75;

    function flickerTick(){
      ctx.clearRect(0, 0, cw, ch);
      drawMatrixGrid(1);
      flickerCount++;
      if(flickerCount < totalFlickers){
        setTimeout(flickerTick, flickerInterval);
      } else {
        crossfadeToPixelated();
      }
    }

    // Phase 2: crossfade from matrix code into a blocky/pixelated version of the photo
    function crossfadeToPixelated(){
      const duration = 650;
      const start = performance.now();
      function frame(now){
        const progress = Math.min(1, (now - start) / duration);
        ctx.clearRect(0, 0, cw, ch);
        drawMatrixGrid(1 - progress);
        drawPhotoLayer(progress, CHUNKY_PIXEL);
        if(progress < 1){
          requestAnimationFrame(frame);
        } else {
          sharpenPhoto();
        }
      }
      requestAnimationFrame(frame);
    }

    // Phase 3: sharpen the blocky photo down to full detail (decrypting feel)
    function sharpenPhoto(){
      const steps = [26, 19, 14, 10, 7, 5, 3, 2, 1];
      let i = 0;
      function nextStep(){
        if(i >= steps.length) return;
        ctx.clearRect(0, 0, cw, ch);
        drawPhotoLayer(1, steps[i]);
        i++;
        setTimeout(nextStep, 110);
      }
      nextStep();
    }

    flickerTick();
  };
})();

