function detectLang(text){
  return /[\u0600-\u06FF]/.test(text) ? 'ar' : 'en';
}

// Normalize Arabic text: strip diacritics, unify letter variants, collapse spaces
function normalize(s){
  return s
    .toLowerCase()
    .replace(/[\u064B-\u0652]/g, '')      // remove harakat/tashkeel
    .replace(/[إأآا]/g, 'ا')               // unify alef forms
    .replace(/ة/g, 'ه')                    // ta marbuta -> ha
    .replace(/ى/g, 'ي')                    // alef maksura -> ya
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/[^\w\u0600-\u06FF\s]/g, ' ') // strip punctuation
    .replace(/\s+/g, ' ')
    .trim();
}

// Simple Levenshtein edit distance, used for typo tolerance
function levenshtein(a, b){
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for(let i = 0; i <= m; i++) dp[i][0] = i;
  for(let j = 0; j <= n; j++) dp[0][j] = j;
  for(let i = 1; i <= m; i++){
    for(let j = 1; j <= n; j++){
      dp[i][j] = Math.min(
        dp[i-1][j] + 1,
        dp[i][j-1] + 1,
        dp[i-1][j-1] + (a[i-1] === b[j-1] ? 0 : 1)
      );
    }
  }
  return dp[m][n];
}

// Matches a keyword against the input even with typos/misspellings
function fuzzyIncludes(rawText, keyword){
  const text = normalize(rawText);
  const kw = normalize(keyword);
  if(!kw) return false;
  if(text.includes(kw)) return true;

  // token-level fuzzy match for single-word keywords (tolerates typos)
  if(!kw.includes(' ')){
    const tokens = text.split(' ');
    const threshold = kw.length <= 4 ? 1 : (kw.length <= 7 ? 2 : 3);
    for(const tok of tokens){
      if(tok.length < 2) continue;
      if(Math.abs(tok.length - kw.length) <= threshold && levenshtein(tok, kw) <= threshold) return true;
    }
  }
  return false;
}

function matchReply(input){
  const lang = detectLang(input);
  for(const rule of RULES){
    for(const kw of rule.kws){
      if(fuzzyIncludes(input, kw)) return KB[rule.key][lang];
    }
  }
  return KB.fallback[lang];
}

function callAI(userText){
  const thinking = appendMsg('msg-sys', '[processing...]');
  const delay = 350 + Math.random() * 350;
  setTimeout(()=>{
    thinking.remove();
    appendMsg('msg-bot', matchReply(userText));
  }, delay);
}

function sendChat(){
  const val = chatlog.value.trim();
  if(!val) return;
  appendMsg('msg-user', val);
  chatlog.value = '';
  callAI(val);
}

function askSuggested(q){
  appendMsg('msg-user', q);
  callAI(q);
}

chatlog.addEventListener('keydown', (e)=>{
  if(e.key === 'Enter') sendChat();
});

